use sgenaxis_work::project_definition::*;
use std::collections::BTreeMap;
fn draft()->DefinitionDraft { DefinitionDraft{name:"Independent".into(),purpose:"review".into(),last_saved_step:WizardStep::Preview,delivery_targets:vec![],topology:FieldState::Unresolved,requirements:vec![],preference_source:PreferenceSource::Skip,template:None,open_decisions:vec![],extensions:BTreeMap::new()} }
fn def()->ProjectDefinition {ProjectDefinition{project_uuid:PersistentProjectId::candidate("11111111-1111-4111-8111-111111111111"),definition_revision:DefinitionRevision(9),draft:draft(),mode:DefinitionMode::Draft,approval_refs:vec![],legacy_root_keys:vec!["root-key".into()]}}
#[test] fn rejection_is_immutable_for_each_invalid_name(){for name in ["", " ","CON","NUL.txt","LPT9","a/b","a:b","x."] {let current=def();let before=current.clone();let mut next=draft();next.name=name.into();assert!(matches!(apply_definition(&current,DefinitionRevision(9),next),Err(DefinitionError::InvalidInput{..})));assert_eq!(current,before);}}
#[test] fn stale_revision_cannot_replace_extensions_or_identity(){let current=def();let mut next=draft();next.extensions.insert("user.note".into(),ExtensionValue::String("changed".into()));assert_eq!(apply_definition(&current,DefinitionRevision(8),next),Err(DefinitionError::RevisionConflict));assert_eq!(current,def());}
#[test] fn nested_extension_and_unresolved_states_survive_pure_apply(){let current=def();let mut next=draft();next.extensions.insert("custom".into(),ExtensionValue::Array(vec![ExtensionValue::Null,ExtensionValue::Bool(true),ExtensionValue::Object(BTreeMap::new())]));let saved=apply_definition(&current,DefinitionRevision(9),next.clone()).unwrap();assert_eq!(saved.draft,next);assert_eq!(saved.project_uuid,current.project_uuid);assert_eq!(saved.legacy_root_keys,current.legacy_root_keys);assert_eq!(saved.definition_revision,DefinitionRevision(10));}
#[test] fn invalid_identity_shapes_never_apply(){for id in ["", "11111111-1111-1111-8111-111111111111","11111111-1111-4111-7111-111111111111","AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA"]{let mut current=def();current.project_uuid=PersistentProjectId::candidate(id);let before=current.clone();assert_eq!(apply_definition(&current,DefinitionRevision(9),draft()),Err(DefinitionError::InvalidInput{field:"projectUuid".into()}));assert_eq!(current,before);}}
#[test] fn duplicate_requirement_ids_are_rejected(){let mut d=draft();let req=DefinitionRequirement{id:"R1".into(),intent:"intent".into(),acceptance:vec!["AC".into()],state:RequirementState::Unresolved};d.requirements=vec![req.clone(),req];assert_eq!(validate_definition(&d),Err(DefinitionError::InvalidInput{field:"requirements[1].id".into()}));}
#[test] fn overflow_cannot_invalidate_existing_approval_data(){let mut current=def();current.definition_revision=DefinitionRevision(u64::MAX);current.approval_refs=vec!["approved".into()];let before=current.clone();let mut next=draft();next.purpose="change".into();assert_eq!(apply_definition(&current,DefinitionRevision(u64::MAX),next),Err(DefinitionError::RevisionOverflow));assert_eq!(current,before);}
